def match_parens(lst):
    def is_good(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]

    # Check both concatenation orders
    if is_good(s1 + s2) or is_good(s2 + s1):
        return 'Yes'
    else:
        return 'No'

